 if(this.screen==='groupLobby'){for(let i=0;i<this.input.padStates.length;i++)if(this.input.padStates[i]?.back&&this.groupSeats.some(s=>s.device==='pad'&&s.pad===i)){this.groupSeats=this.groupSeats.filter(s=>s.device!=='pad'||s.pad!==i);this.groupLobby();return;}if(this.input.keyboard.back&&this.groupSeats.some(s=>s.device==='kbm')){this.groupSeats=this.groupSeats.filter(s=>s.device!=='kbm');this.groupLobby();return;}let joined=false;for(let i=0;i<this.input.padStates.length;i++){let p=this.input.padStates[i];if(p?.confirm&&!this.groupSeats.some(s=>s.device==='pad'&&s.pad===i)){this.joinGroup('pad',i);joined=true;}}if(this.input.keyboard.confirm&&!this.groupSeats.some(s=>s.device==='kbm')){this.joinGroup('kbm',0);joined=true;}if(joined)return;}
 if(this.screen==='speech'){this.island.fixed(dt,{x:0,z:0},'idle');if(s.confirm&&this.stateTime>.25){const next=this.speechNext;this.speechNext=null;next?.();}return;}
