 if(this.screen==='age'){if(this.stateTime<2.4){this.ui.screen.querySelector('#age-counter').textContent=18+Math.floor((this.stateTime*49)%82);if(Math.floor(this.stateTime*16)!==this.ageRollTick){this.ageRollTick=Math.floor(this.stateTime*16);this.audio.sfx('move');}}else if(!this.ageShown){this.ageShown=true;this.ui.screen.querySelector('#age-counter').textContent=this.currentAge;let text=this.currentAge>55?line('highAge'):line('lowAge');this.ui.screen.querySelector('#age-line').textContent=text;this.ui.screen.querySelector('#age-continue').hidden=false;this.audio.sting('Pleasant');this.audio.say(text,'Trudy');}this.ui.poll(dt,s);return;}
