 if(this.screen==='ending'){this.island.fixed(dt,{x:0,z:0},'idle');let beat=Math.floor(this.stateTime/6),text=['Oh. So that’s what the middle looks like.','', 'It’s quite flat, isn’t it?', '…Same time tomorrow?'][Math.min(3,beat)];if(beat!==this.endingBeat){this.endingBeat=beat;this.ui.show(`<div class="topline"><div class="tag gold">The island is level.</div></div>${text?`<div class="speech"><span class="name">Trudy</span>${text}${beat>=3?`<div class="footer">${btn('A very small curtain call','credits','','primary')}</div>`:''}</div>`:''}`,{credits:()=>this.about(0,true)});if(text)this.audio.say(text,'Trudy');if(beat===1)this.audio.sting('Suspicious');}if(s.confirm&&beat>=3)this.about(0,true);return;}
 if(this.screen==='podium'&&this.event){this.event.fixed(dt,this.event.lanes.map(()=>({x:0,z:0})));if(this.stateTime>2&&this.podiumRoot)this.podiumRoot.rotation.z=Math.min(.9,(this.stateTime-2)*.1);}
 if(['title','menu','profiles','newProfile','question','checkIntro','intro','results','plan','bed','free','tiers','pause','settings','how','dev','journal','mirror','about','groupLobby','groupPlaylist','podium','resetConfirm'].includes(this.screen)){this.ui.poll(dt,s);}
