 state(){return {screen:this.screen,attract:this.attract,attractId:this.attractId,day:this.profile?.day||0,step:this.profile?.steps||0,profile:this.profile?JSON.parse(JSON.stringify(this.profile)):null,marbles:this.profile?.marbles||0,tilt:restTilt(this.profile?.steps||0),wobbleAge:this.profile?.ages.at(-1)?.age||0,event:this.event?.state()||null,input:{lastDevice:this.input.lastDevice,glyphSet:this.settings.glyphs,...this.lastInput},audio:{state:this.audio.ctx?.state||'silent',music:this.settings.music,sfx:this.settings.sfx,voice:this.settings.voice,detune:this.audio.detune(this.simTime)},render:{backend:this.view.backend,frames:this.view.frames,sceneFrames:this.view.ink?.stats.sceneFrames||0,nodeFrame:this.view.renderer?.info.frame||0,lost:this.view.lost},world:this.simTime,errors:[...this.errors]};}
 goto(screen,args={}){switch(screen){case 'title':this.title();break;case 'menu':this.mainMenu();break;case 'profile':if(!this.profile){this.save.data.profiles[0]=freshProfile();this.save.data.selected=0;this.profile.tutorial=true;}this.island.setProfile(this.profile);this.showIsland();break;case 'event':this.flow='free';this.groupRun=null;this.intro(args.id||'fruit',args.tier||1);if(args.play)this.beginPlay();break;case 'island':this.showIsland();break;case 'plan':this.todayPlan();break;case 'pause':this.pause();break;case 'about':this.about(args.page||0);break;case 'ending':this.ending();break;case 'jar':this.jarView(args.count||10,()=>this.showIsland());break;case 'age':this.ageShown=false;this.ageReveal(args.age||74);break;case 'group':this.groupLobby();break;case 'settings':this.settingsMenu(this.screen);break;case 'dev':if(this.screen==='pause')this.devMenu();break;case 'check':this.startCheck();this.beginPlay();break;case 'journal':this.journal(args.page||0);break;}}
